/** Independent witness checks for the bounded, actual SOCIAL_MEDIA catalog queries. */
class SocialMediaOracleFixtureCoverageTest {
	private static final String NS = SocialMediaOracleFixtureProfile.NAMESPACE;
	private static final IRI FOLLOWS = SocialMediaOracleFixtureProfile.iri("follows");
	private static final IRI NAME = SocialMediaOracleFixtureProfile.iri("name");

	@Test
	void actualCatalogCountsDegreesAndBranchesHavePositiveAndNegativeWitnesses() {
		Model fixture = SocialMediaOracleFixtureProfile.generate();
		assertEquals(18, fixture.filter(null, RDF.TYPE, SocialMediaOracleFixtureProfile.iri("User")).size());
		assertEquals(3, fixture.filter(null, RDF.TYPE, SocialMediaOracleFixtureProfile.iri("Post")).size());
		assertTrue(fixture.contains(SocialMediaOracleFixtureProfile.iri("post/7a"),
				SocialMediaOracleFixtureProfile.iri("authored"), user(7)));
		assertFalse(fixture.contains(user(7), SocialMediaOracleFixtureProfile.iri("authored"),
				SocialMediaOracleFixtureProfile.iri("post/7a")));
		assertFalse(fixture.contains(user(14), NAME, null));
		assertFalse(fixture.contains(user(4), FOLLOWS, user(6)));
		assertEquals(2, fixture.filter(user(4), FOLLOWS, null).size(), "q3 has a below-threshold user");
		assertEquals(1, fixture.filter(user(13), FOLLOWS, null).size(), "q6 has a below-threshold user");
		assertTrue(fixture.contains(user(1), FOLLOWS, user(1)));
		assertTrue(fixture.contains(user(10), FOLLOWS, user(10)));
		Dataset dataset = ThemeOracleBundleTool.jenaDataset(fixture);
		try {
			int[] indexes = { 0, 1, 2, 4, 5, 7, 8, 9, 10 };
			// q5 includes user10 as a reciprocal activity through its self-follow, as well as users 7 and 8.
			long[] counts = { 6, 1, 4, 3, 5, 3, 3, 4, 2 };
			for (int i = 0; i < indexes.length; i++) {
				assertEquals(counts[i], count(dataset, indexes[i]), "actual positive COUNT at q" + indexes[i]);
			}
			List<QuerySolution> q3 = select(dataset, query(3));
			assertEquals(1, q3.size());
			assertEquals(user(3).stringValue(), q3.get(0).getResource("u").getURI());
			assertEquals(3, q3.get(0).getLiteral("degree").getLong());
			List<QuerySolution> q6 = select(dataset, query(6));
			assertEquals(1, q6.size());
			assertEquals(user(12).stringValue(), q6.get(0).getResource("u").getURI());
			assertEquals(5, q6.get(0).getLiteral("connections").getLong());
			assertTrue(ask(dataset, "<" + user(7) + "> <" + FOLLOWS + "> <" + user(8) + "> . "
					+ "<" + user(8) + "> <" + FOLLOWS + "> <" + user(7) + "> . "
					+ "<" + user(7) + "> <" + NAME + "> \"user7\" ."), "q5 reciprocal-follow branch");
			assertTrue(ask(dataset, "<" + NS + "post/7a> <" + NS + "authored> <" + user(7) + "> . "
					+ "<" + user(7) + "> <" + NAME + "> \"user7\" ."), "q5 authored-post branch");
		} finally {
			dataset.close();
		}

		Model withoutSelf = new LinkedHashModel(fixture);
		withoutSelf.remove(user(1), FOLLOWS, user(1));
		Dataset minusControl = ThemeOracleBundleTool.jenaDataset(withoutSelf);
		try {
			assertEquals(2, count(minusControl, 1), "q1 MINUS excludes a real self-follow match");
		} finally {
			minusControl.close();
		}
	}

	@Test
	void q9HasAFourDistinctVertexWalkAsWellAsRepeatedPositionSolutions() {
		String q9 = query(9);
		String aggregate = "SELECT (COUNT(DISTINCT ?a) AS ?count) WHERE {";
		assertTrue(q9.contains(aggregate));
		assertTrue(q9.contains("  OPTIONAL {"));
		String distinctWitness = q9.replace(aggregate, "SELECT ?a ?b ?c ?d WHERE {")
				.replace("  OPTIONAL {", "  FILTER(?a != ?c && ?b != ?d)\n  OPTIONAL {");
		Dataset dataset = ThemeOracleBundleTool.jenaDataset(SocialMediaOracleFixtureProfile.generate());
		try {
			assertFalse(select(dataset, distinctWitness).isEmpty(),
					"q9 fixture must also exercise a four-distinct-vertex cycle");
		} finally {
			dataset.close();
		}
	}

	@Test
	void cycleControlsDoNotRelyOnMissingEdgesHiddenByAlternativeWalks() {
		Model fixture = SocialMediaOracleFixtureProfile.generate();
		assertCycleControl(fixture, 8, new int[][] { { 0, 1 }, { 1, 2 }, { 2, 0 } }, 3, 2, 0);
		// q9 permits a=c and b=d; this two-edge reciprocal walk is a catalog solution.
		assertCycleControl(fixture, 9, new int[][] { { 3, 4 }, { 4, 3 } }, 2, 3, 4);
		// q10 permits e=a; the final self edge closes this five-edge walk with four distinct users.
		assertCycleControl(fixture, 10, new int[][] { { 8, 9 }, { 9, 10 }, { 10, 11 }, { 11, 8 },
				{ 8, 8 } }, 1, 8, 8);
	}

	@Test
	void q11KeepsTiedOptionalFanoutAndQ12EliminatesActualDuplicateMappings() {
		Dataset dataset = ThemeOracleBundleTool.jenaDataset(SocialMediaOracleFixtureProfile.generate());
		try {
			List<QuerySolution> q11 = select(dataset, query(11));
			List<QuerySolution> tied = q11.stream()
					.filter(row -> is(row, "root", user(7))
							&& is(row, "followed", user(8))
							&& is(row, "post", SocialMediaOracleFixtureProfile.iri("post/7a")))
					.toList();
			assertTrue(tied.size() >= 2, "same ORDER BY keys must have multiple distinct rows");
			assertTrue(tied.stream().anyMatch(row -> "user7".equals(row.getLiteral("rootName").getString())));
			assertTrue(tied.stream().anyMatch(row -> "user7-alias".equals(row.getLiteral("rootName").getString())));
			assertTrue(q11.stream()
					.anyMatch(row -> is(row, "root", user(12)) && is(row, "followed", user(14))
							&& !row.contains("followedName") && !row.contains("followedFollows")),
					"nested OPTIONAL remains unbound when followed user lacks a name");

			String q12 = query(12);
			assertTrue(q12.contains("SELECT DISTINCT * WHERE"));
			Bag actualDistinct = bag(dataset, q12);
			Bag raw = bag(dataset, q12.replace("SELECT DISTINCT * WHERE", "SELECT * WHERE"));
			assertTrue(raw.totalMultiplicity() > actualDistinct.totalMultiplicity(),
					"q12 DISTINCT eliminates duplicates");
			int root = raw.variableNames().indexOf("root");
			int follower = raw.variableNames().indexOf("optFollower");
			assertTrue(root >= 0 && follower >= 0);
			assertTrue(raw.rows()
					.stream()
					.anyMatch(row -> row.multiplicity() > 1
							&& user(7).equals(row.row().values().get(root))
							&& user(8).equals(row.row().values().get(follower))),
					"reciprocal incoming/outgoing UNION branches duplicate the same mapping");
			Bag deduplicated = SolutionBagCodec.fromRows(raw.variableNames(),
					raw.rows().stream().map(row -> row.row()).toList());
			assertTrue(SolutionBagCodec.isomorphic(deduplicated, actualDistinct));
		} finally {
			dataset.close();
		}
	}

	private static void assertCycleControl(Model fixture, int index, int[][] edges, long expected, int cutFrom,
			int cutTo) {
		Model isolated = new LinkedHashModel(fixture.filter(null, NAME, null));
		for (int[] edge : edges) {
			assertTrue(fixture.contains(user(edge[0]), FOLLOWS, user(edge[1])));
			isolated.add(user(edge[0]), FOLLOWS, user(edge[1]));
		}
		Dataset complete = ThemeOracleBundleTool.jenaDataset(isolated);
		try {
			assertEquals(expected, count(complete, index), "isolated q" + index + " cycle witness");
		} finally {
			complete.close();
		}
		assertEquals(edges.length, isolated.filter(null, FOLLOWS, null).size(), "no alternative edges in control");
		isolated.remove(user(cutFrom), FOLLOWS, user(cutTo));
		Dataset broken = ThemeOracleBundleTool.jenaDataset(isolated);
		try {
			assertEquals(0, count(broken, index), "removing the required edge eliminates every isolated walk");
		} finally {
			broken.close();
		}
	}

	private static String query(int index) {
		return ThemeQueryCatalog.queryFor(Theme.SOCIAL_MEDIA, index);
	}

	private static long count(Dataset dataset, int index) {
		List<QuerySolution> rows = select(dataset, query(index));
		assertEquals(1, rows.size());
		return rows.get(0).getLiteral("count").getLong();
	}

	private static List<QuerySolution> select(Dataset dataset, String query) {
		List<QuerySolution> rows = new ArrayList<>();
		dataset.begin(ReadWrite.READ);
		try (QueryExecution execution = QueryExecution.dataset(dataset).query(query).build()) {
			var result = execution.execSelect();
			while (result.hasNext()) {
				rows.add(result.nextSolution());
			}
		} finally {
			dataset.end();
		}
		return rows;
	}

	private static Bag bag(Dataset dataset, String query) {
		dataset.begin(ReadWrite.READ);
		try (QueryExecution execution = QueryExecution.dataset(dataset).query(query).build()) {
			var result = execution.execSelect();
			List<String> variables = List.copyOf(result.getResultVars());
			List<Row> rows = new ArrayList<>();
			while (result.hasNext()) {
				QuerySolution solution = result.nextSolution();
				List<Value> values = new ArrayList<>();
				for (String variable : variables) {
					values.add(ThemeOracleBundleTool.toRdf4j(solution.get(variable)));
				}
				rows.add(new Row(values));
			}
			return SolutionBagCodec.fromRows(variables, rows);
		} finally {
			dataset.end();
		}
	}

	private static boolean ask(Dataset dataset, String pattern) {
		dataset.begin(ReadWrite.READ);
		try (QueryExecution execution = QueryExecution.dataset(dataset)
				.query("ASK WHERE { " + pattern + " }")
				.build()) {
			return execution.execAsk();
		} finally {
			dataset.end();
		}
	}

	private static boolean is(QuerySolution row, String variable, IRI value) {
		return row.contains(variable) && row.get(variable).isURIResource()
				&& value.stringValue().equals(row.getResource(variable).getURI());
	}

	private static IRI user(int id) {
		return SocialMediaOracleFixtureProfile.user(id);
	}
}
